const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries
  const point1 = ee.Geometry.Point([63.8577134531586, -22.413665983340525]);
  const grindavik = ee.Geometry.Point([63.84, -22.43]); // Grindavik center

  const startDate = '2024-01-16';
  const endDate = '2024-01-17';

  try {
    // 2. Get MODIS LST data (Terra)
    let lstCollection = ee.ImageCollection('MODIS/061/MOD11A1')
      .filterDate(startDate, endDate)
      .filterBounds(point1)
      .select('LST_Day_1km');

    let collectionSize = await lstCollection.size().getInfo();

    // Fallback to Aqua MODIS if Terra has no data
    if (collectionSize === 0) {
      console.log("No Terra MODIS data, trying Aqua MODIS...");
      lstCollection = ee.ImageCollection('MODIS/061/MYD11A1')
        .filterDate(startDate, endDate)
        .filterBounds(point1)
        .select('LST_Day_1km');

      collectionSize = await lstCollection.size().getInfo();
    }

    if (collectionSize === 0) {
      console.log("No MODIS data found for Jan 16, 2024.");
      console.log("<answer>C1</answer>");
      return;
    }

    console.log(`Found ${collectionSize} MODIS image(s)`);

    // 3. Get the image and convert to Celsius (MODIS LST is in Kelvin * 0.02)
    const lstImage = lstCollection.mean();
    const lstCelsius = lstImage.multiply(0.02).subtract(273.15);

    // 4. Sample at both points
    const temp1Result = await lstCelsius.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: point1,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const temp2Result = await lstCelsius.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: grindavik,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const temp1 = temp1Result.LST_Day_1km;
    const temp2 = temp2Result.LST_Day_1km;

    // 5. Check for valid data
    if (temp1 === null || temp2 === null || isNaN(temp1) || isNaN(temp2)) {
      console.log(`Temp at point1: ${temp1}, Temp at Grindavik: ${temp2}`);
      console.log("Invalid temperature data (null or NaN).");
      console.log("<answer>C2</answer>");
      return;
    }

    // Sanity check for reasonable temperature range
    if (temp1 < -100 || temp1 > 100 || temp2 < -100 || temp2 > 100) {
      console.log(`Unrealistic temperatures: ${temp1}C, ${temp2}C`);
      console.log("<answer>C3</answer>");
      return;
    }

    console.log(`Temperature at (63.858, -22.414): ${temp1.toFixed(2)}°C`);
    console.log(`Temperature at Grindavik center: ${temp2.toFixed(2)}°C`);

    // 6. Compare and answer
    if (temp1 > temp2) {
      console.log(`${temp1.toFixed(2)} > ${temp2.toFixed(2)}: Point 1 is warmer`);
      console.log("<answer>A</answer>");
    } else {
      console.log(`${temp1.toFixed(2)} <= ${temp2.toFixed(2)}: Point 1 is not warmer`);
      console.log("<answer>B</answer>");
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log("<answer>D</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
